//
//  PDFReportTests.swift
//  GuitarTapTests
//
//  A saved measurement's PDF report, as the measurement list exports it (PDFReportGenerator.report(for:)),
//  read back line by line and compared with the expected lines beside its fixture (`<fixture>.pdf.txt`):
//  each line's page, its height on the page and its words. A line's height is its baseline's distance from
//  the page's top — for a line mixing sizes, the baseline of its largest text — and must be within 1 pt of
//  the expected. Words are compared with whitespace removed. The measurement's date and the "Generated by …"
//  line are matched by position only (they depend on the locale, the time and the build). The expected
//  lines are Swift's; the Python and web suites have the same cases and the same expected files.
//
// @parity test/pdf-report

import Foundation
import PDFKit
import Testing
@testable import GuitarTap

private final class PDFReportTestsAnchor {}

@Suite("PDFReport", .serialized)
@MainActor
struct PDFReportTests {

    /// The shared cases: each fixture, through the report its kind uses, and the baseline tolerance.
    // nonisolated: @Test(arguments:) reads the case table outside the main actor, the target's default;
    // (unsafe) because `Any` cannot be Sendable — the table is immutable once loaded.
    nonisolated(unsafe) static let data: [String: Any] = {
        let url = Bundle(for: PDFReportTestsAnchor.self).url(forResource: "pdf-report", withExtension: "json")!
        return try! JSONSerialization.jsonObject(with: Data(contentsOf: url)) as! [String: Any]
    }()
    nonisolated static let fixtures = data["fixtures"] as! [String]

    @Test(arguments: fixtures)
    func report_matchesTheExpectedLines(_ fixture: String) throws {
        let bundle = Bundle(for: PDFReportTestsAnchor.self)
        let fileURL = try #require(bundle.url(forResource: fixture, withExtension: "guitartap"))
        let expectedURL = try #require(bundle.url(forResource: fixture + ".guitartap.pdf", withExtension: "txt"))
        let measurement = try #require(try TapToneAnalyzer.decodeMeasurements(Data(contentsOf: fileURL)).first)
        let report = try #require(PDFReportGenerator.report(for: measurement))
        let document = try #require(PDFDocument(data: report.data))

        let date = Self.squeezed([DateDisplay.string(measurement.timestamp)])
        let actual = Self.lines(of: document).map { line in
            Line(page: line.page, baseline: line.baseline,
                 text: Self.squeezed([line.text]) == date ? "<date>"
                     : line.text.hasPrefix("Generated by") ? "<generated>" : line.text)
        }
        let expected = try String(contentsOf: expectedURL, encoding: .utf8).split(separator: "\n").map { row in
            let fields = row.split(separator: "\t", maxSplits: 2).map(String.init)
            return Line(page: Int(fields[0])!, baseline: Double(fields[1])!, text: fields[2])
        }
        let listing = "\(fixture):\n--- actual\n\(actual.map(\.description).joined(separator: "\n"))"
            + "\n--- expected\n\(expected.map(\.description).joined(separator: "\n"))"
        try #require(actual.count == expected.count, "line count \(actual.count) ≠ \(expected.count)\n\(listing)")
        for (a, e) in zip(actual, expected) {
            #expect(a.page == e.page && abs(a.baseline - e.baseline) <= (Self.data["baselineTolerance"] as! Double)
                        && Self.squeezed([a.text]) == Self.squeezed([e.text]),
                    "\(a) ≠ expected \(e)\n\(listing)")
        }
    }

    /// One line of a page: its page index, its baseline's distance from the page's top, and its text.
    struct Line: CustomStringConvertible {
        let page: Int
        let baseline: Double
        let text: String
        var description: String { String(format: "%d\t%.1f\t", page, baseline) + text }
    }

    /// The pages' lines by position: PDFKit's line selections, grouped into lines by baseline (top to
    /// bottom), each line left to right. A selection's baseline is its top plus the ascender of its
    /// largest font (PDFKit merges text of different sizes on one line into one selection).
    static func lines(of document: PDFDocument) -> [Line] {
        typealias Run = (baseline: Double, x: Double, size: Double, text: String)
        var out: [Line] = []
        for index in 0..<document.pageCount {
            guard let page = document.page(at: index),
                  let all = page.selection(for: page.bounds(for: .mediaBox)) else { continue }
            let height = page.bounds(for: .mediaBox).height
            let runs = all.selectionsByLine().compactMap { selection -> Run? in
                guard let text = selection.string?.trimmingCharacters(in: .whitespacesAndNewlines), !text.isEmpty,
                      let attributed = selection.attributedString
                else { return nil }
                var largest: PlatformFont?
                attributed.enumerateAttribute(.font, in: NSRange(location: 0, length: attributed.length)) { value, _, _ in
                    if let font = value as? PlatformFont, font.pointSize > (largest?.pointSize ?? 0) { largest = font }
                }
                let bounds = selection.bounds(for: page)
                return (Double(height - bounds.maxY + (largest?.ascender ?? 0)), Double(bounds.minX),
                        Double(largest?.pointSize ?? 0), text)
            }.sorted { $0.baseline < $1.baseline }
            var rows: [[Run]] = []
            for run in runs {
                if let last = rows.last, abs(last[0].baseline - run.baseline) < 3 { rows[rows.count - 1].append(run) }
                else { rows.append([run]) }
            }
            out += rows.map { row in
                let largest = row.reduce(row[0]) { $1.size > $0.size + 0.01 ? $1 : $0 }
                return Line(page: index, baseline: largest.baseline,
                            text: row.sorted { $0.x < $1.x }.map(\.text).joined(separator: " "))
            }
        }
        return out
    }

    /// The lines joined, without whitespace, in Unicode compatibility form (a ligature reads as its letters).
    static func squeezed(_ lines: [String]) -> String {
        lines.joined().precomposedStringWithCompatibilityMapping.filter { !$0.isWhitespace }
    }
}
